{"meta":{"lessonId":"grade_3_urdu_ch15_seg4","grade":3,"subject":"urdu","language":"ur","topic":"رموزِ اوقاف — قوسین، استفہامیہ وغیرہ","chapterTitle":"باب ۱۵ · بچوں کے لیے اقبال رحمت اللہ علیہ کا پیغام","minutes":40,"sloDescriptions":["میں جملے میں ۔ ، ؟ اور ( ) درست جگہ لگا سکتا/سکتی ہوں۔"],"source":"v9_html","adapterV":2},"goal":"میں جملے میں ۔ ، ؟ اور ( ) درست جگہ لگا سکتا/سکتی ہوں۔","sloFull":"میں جملے میں ۔ ، ؟ اور ( ) درست جگہ لگا سکتا/سکتی ہوں۔","sloCode":"U-03-GR-15","hook":{"minutes":4,"warmUp":{"teacherAsks":"صفحہ ۱۵۱ کھولیں۔ 'تمھارا نام کیا ہے؟' کے آخر میں کون سا نشان ہے؟","expectedAnswer":"← سوالیہ نشان ؟۔"},"conversation":[{"teacherAsks":"سب مل کر بتائیں: یہ نشان کیوں لگا؟ متوقع: کیونکہ یہ سوال ہے۔ آج کا ہدف: میں جملے میں ۔ ، ؟ اور ( ) درست جگہ لگا سکتا/سکتی ہوں۔"}],"keyWords":[{"term":"رموزِ اوقاف","def":"وہ نشان جو جملے کے وقفے سمجھنے میں مدد دیتے ہیں"},{"term":"قوسین ( )","def":"وضاحتی بات کے گرد"}],"materials":["اردو کی درسی کتاب صفحہ ۱۵۰-۱۵۲","طلباء کی کاپیاں"]},"iDo":{"minutes":8,"steps":[{"n":1,"action":"کتاب کے صفحہ ۱۵۱ پر مثالوں کی طرف اشارہ کریں: بات ختم تو ختمہ ۔، سوال تو ؟۔"},{"n":2,"action":"اسی صفحہ کی مثال (الف) دکھائیں: 'تعلیم آباد والے' ہٹا کر پڑھیں؛ جملہ پھر بھی پورا ہے، اس لیے یہ وضاحت ہے اور اس کے گرد ( ) آتے ہیں۔"},{"n":3,"say":"عام غلطی کی نشان دہی کریں: 'کیا' سے شروع جملے کے آخر میں ۔ لگانا غلط ہے، سوال کے آخر میں ؟ آتا ہے۔"},{"n":4,"say":"فوری جانچ: 'تمہارا نام کیا ہے' کے آخر میں کیا نشان آئے گا؟ سب ہوا میں انگلی سے لکھیں۔ متوقع: ؟۔"}],"cfu":"سب مل کر بتائیں: سوال کے آخر میں کون سا نشان؟ متوقع: ؟۔","misconception":{"slip":"کیا تم میرے گھر آ رہے ہو۔","fix":"یہ بات بتا رہا ہے یا پوچھ رہا ہے؟ تو آخر میں ؟ لگے گا۔"}},"weDo":{"minutes":12,"strategy":"نشان کی حرکت کا کھیل: استاد جملہ بولیں، بچے ہاتھ کی حرکت سے نشان بتائیں۔","steps":[{"n":1,"action":"کہیں: 'میں جملہ بولوں گی۔ اگر بات ختم ہو تو مٹھی بند کریں، سوال ہو تو انگلی اوپر اٹھائیں۔' صفحہ ۱۵۱ کے سوال ۲ کے چاروں جملے باری باری بولیں اور پوری جماعت سے مل کر حرکت کروائیں۔"},{"n":2,"action":"صفحہ ۱۵۱ کا سوال ۱ (الف) کتاب میں سب سے مل کر پڑھیں: 'جوجو اور پنکی (تعلیم آباد والے)...' پوچھیں: اضافی بات کون سی ہے؟ سب مل کر جواب دیں، متوقع: تعلیم آباد والے۔ اگر کوئی غلط بولے تو کہیں: اسے ہٹا کر پڑھو، جملہ پورا بنتا ہے؟"}]},"youDo":{"minutes":12,"steps":[{"n":1,"action":"کہیں: 'اب ہر بچہ اکیلا کاپی میں کام کرے: سوال ۱ (ب، ج) اور سوال ۲ (ج، د)، صفحہ ۱۵۱۔ تالی پر قلم رکھ دیں۔'"},{"n":2,"action":"جو بچے تیز ہیں وہ صفحہ ۱۵۲ کا اقتباس 'مجھے کل سے بخار تھا...' کاپی میں لکھ کر درست نشان لگائیں۔"}],"problems":[{"n":1,"prompt":"سوال ۱ (ب): کہانیوں کی کتاب جو تحفہ تھی کل رات سے نہیں مل رہی۔ (قوسین لگائیں)","answer":"کہانیوں کی کتاب (جو تحفہ تھی) کل رات سے نہیں مل رہی۔"},{"n":2,"prompt":"سوال ۲ (ج): میں نے کتابیں قلم اور کاپی خریدی","answer":"میں نے کتابیں، قلم اور کاپی خریدی۔"}],"behind":{"prompt":"استاد پوچھے: بات بتائی یا پوچھی؟ پھر بچہ خود نشان لگائے۔"},"ahead":{"prompt":"صفحہ ۱۵۲ کا اقتباس کاپی میں لکھ کر درست نشان لگائیں۔"}},"wrap":{"minutes":4,"exitOptions":[{"prompt":"کتاب کے صفحہ ۱۵۱ میں سوال ۲ (ب) کی طرف اشارہ کریں: 'کیا تم میرے گھر آ رہے ہو' سب مل کر بلند آواز سے پڑھیں۔ پوچھیں: آخر میں کون سا نشان آئے گا اور کیوں؟ سب انگوٹھے سے بتائیں: ٹھیک سمجھ آیا تو اوپر، نہیں تو نیچے۔","answer":"← سوالیہ نشان ؟، کیونکہ یہ سوال ہے۔"}],"reteach":"بات ختم ہو تو ۔، سوال ہو تو ؟، وقفہ یا فہرست ہو تو ،، اضافی وضاحت ہو تو ( )۔","homework":["کاپی میں اپنے دو جملے لکھیں: ایک سوال اور ایک تین چیزوں کی فہرست والا؛ ہر جملے میں درست رموزِ اوقاف لگائیں۔"]}}
